struct Data { int x = 0; };

// 1. Creation (Exclusive ownership)
auto u_ptr = std::make_unique<Data>();

// 2. Access
u_ptr->x = 5;

// 3. Ownership transfer via move (cannot copy)
auto u_ptr_2 = std::move(u_ptr); 

// 4. u_ptr is now null
if (!u_ptr) { 
    // u_ptr_2 now owns the Data object
}

// 5. Manual release (stops automated management)
Data* raw_ptr = u_ptr_2.release();
delete raw_ptr; 
// Resource deleted when u_ptr_2 goes out of scope

// --- Shared Ptr ---

struct Resource {};

// 1. Creation (Reference counted ownership)
auto s_ptr_A = std::make_shared<Resource>();

// 2. Copying increases reference count (A and B share)
auto s_ptr_B = s_ptr_A; 

// 3. Access reference count
size_t count = s_ptr_A.use_count(); // Returns 2

// 4. Resetting one pointer (count becomes 1)
s_ptr_A.reset();

// 5. Resource is deleted only when count hits 0

// --- Weak Ptr (Non-Owning) ---

auto primary = std::make_shared<int>(100);

// 1. Weak pointer created from shared_ptr
std::weak_ptr<int> secondary(primary);

// 2. Check validity and temporarily gain ownership
if (auto temp = secondary.lock()) {
    int value = *temp; // Valid access
} 

// 3. Destroy primary owner
primary.reset(); 

// 4. Check if resource still exists
if (secondary.expired()) { 
    // Resource destroyed
}
